(function(){
'use strict';
var moneyFmt=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'});
function all(){return window.data&&Array.isArray(data.products)?data.products:[]}
function byId(id){return typeof window.product==='function'?product(id):all().find(function(p){return String(p.id)===String(id)})}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]})}
function money(v){return moneyFmt.format(Number(v||0))}
function typeOf(p){var t=String(p&&p.productType||'Standard Product').toLowerCase();if(t==='bundle'||t==='bundle product')return 'Bundle Product';if(t==='service')return 'Service';if(t==='digital'||t==='digital product')return 'Digital Product';if(t==='variable'||t==='variable product')return 'Variable Product';return 'Standard Product'}
function isBundle(p){return !!p&&typeOf(p)==='Bundle Product'}
function rows(p){return Array.isArray(p&&p.bundleItems)?p.bundleItems.filter(function(r){return r&&r.productId&&Number(r.qty)>0}):[]}
function rawStock(p){if(!p)return {onHand:0,allocated:0,available:0};var fn=window.__poolShedOriginalProductStockSummary||window.productStockSummary;try{return fn?fn(p.id):{onHand:Number(p.stock||0),allocated:0,available:Number(p.stock||0)}}catch(e){return {onHand:Number(p.stock||0),allocated:0,available:Number(p.stock||0)}}}
function flatten(p,mult,trail,out){mult=mult||1;trail=trail||[];out=out||[];if(!p)return out;if(trail.indexOf(p.id)>=0)throw new Error('Circular bundle detected');if(!isBundle(p)){out.push({product:p,qty:mult});return out}var next=trail.concat(p.id);rows(p).forEach(function(r){flatten(byId(r.productId),mult*Number(r.qty||1),next,out)});return out}
function mergedComponents(p){var map={};flatten(p,1,[],[]).forEach(function(r){if(!r.product)return;map[r.product.id]=map[r.product.id]||{product:r.product,qty:0};map[r.product.id].qty+=r.qty});return Object.keys(map).map(function(k){return map[k]})}
function calc(p){var direct=rows(p), flat=[];try{flat=mergedComponents(p)}catch(e){return {error:e.message,cost:0,componentRrp:0,weight:0,available:0,onHand:0,count:0,lines:[],warnings:[e.message]}}
 var cost=0,rrp=0,weight=0,available=Infinity,onHand=Infinity,warnings=[],suppliers={},limiter=null;
 flat.forEach(function(r){var c=r.product,s=rawStock(c),q=Math.max(1,Number(r.qty));cost+=Number(c.cost||0)*q;rrp+=Number(c.rrp||0)*q;weight+=Number(c.weight||0)*q;var av=Math.floor(Number(s.available||0)/q),oh=Math.floor(Number(s.onHand||0)/q);if(av<available){available=av;limiter=c}onHand=Math.min(onHand,oh);suppliers[c.supplier||'Supplier to confirm']=true;if(String(c.status||'Live').toLowerCase()==='archived'||String(c.status||'').toLowerCase()==='discontinued')warnings.push((c.sku||c.name)+' is discontinued or archived.');});
 if(!flat.length){available=0;onHand=0;warnings.push('Add at least one component before activating this bundle.')}var priceMode=p.bundlePriceMode||'fixed',discount=Number(p.bundleDiscountPercent||0),sell=priceMode==='sum-discount'?rrp*(1-discount/100):priceMode==='sum'?rrp:Number(p.bundleManualRrp||p.rrp||0);var profit=sell-cost,margin=sell>0?profit/sell*100:0,saving=Math.max(0,rrp-sell);if(sell<cost)warnings.push('Bundle selling price is lower than total component cost.');if(margin<Number(p.bundleTargetMargin||25))warnings.push('Margin is below the target of '+Number(p.bundleTargetMargin||25).toFixed(0)+'%.');if(available<=0&&flat.length)warnings.push('This bundle cannot currently be fulfilled.');return {cost:cost,componentRrp:rrp,sell:sell,profit:profit,margin:margin,saving:saving,weight:weight,shippingWeight:weight+Number(p.bundlePackagingWeight||0),available:available,onHand:onHand,count:direct.length,totalUnits:flat.reduce(function(a,r){return a+r.qty},0),lines:flat,warnings:warnings,suppliers:Object.keys(suppliers),limiter:limiter}}
function status(c){if(c.available<=0)return {key:'red',label:'Insufficient stock'};if(c.warnings.length)return {key:'amber',label:'Needs attention'};return {key:'green',label:'Ready to sell'}}
function img(p){var src=p.imageUrl||p.parentImageUrl||'';return src?'<img src="'+esc(src)+'" alt="">':'<span class="b2-img-fallback">PS</span>'}
function directRow(r){var c=byId(r.productId);if(!c)return '';var stock=isBundle(c)?calc(c):rawStock(c),av=isBundle(c)?stock.available:stock.available;return '<div class="b2-component" data-b2-row="'+esc(c.id)+'"><div class="b2-product">'+img(c)+'<div><strong>'+esc(c.name)+'</strong><span>'+esc(c.sku||'No SKU')+(isBundle(c)?' · Nested bundle':'')+'</span></div></div><label class="b2-qty">Qty<input type="number" min="1" step="1" value="'+Number(r.qty||1)+'" data-b2-qty="'+esc(c.id)+'"></label><div><span>Available</span><strong class="b2-stock '+(av<=0?'red':av<Number(r.qty||1)?'amber':'green')+'">'+Number(av||0)+'</strong></div><div><span>Cost</span><strong>'+money((isBundle(c)?calc(c).cost:Number(c.cost||0))*Number(r.qty||1))+'</strong></div><div><span>RRP</span><strong>'+money((isBundle(c)?calc(c).sell:Number(c.rrp||0))*Number(r.qty||1))+'</strong></div><div class="b2-row-actions"><button type="button" data-b2-open="'+esc(c.id)+'" title="Open product">Open</button><button type="button" class="danger" data-b2-remove="'+esc(c.id)+'" title="Remove">×</button></div></div>'}
function dashboard(p,c){var st=status(c),warningHtml=c.warnings.length?c.warnings.map(function(w){return '<div class="b2-warning"><span>!</span><p>'+esc(w)+'</p></div>'}).join(''):'<div class="b2-good">All bundle checks passed.</div>';return '<aside class="b2-side"><div class="b2-health '+st.key+'"><span>Bundle health</span><strong>'+st.label+'</strong><em>'+c.available+' available now</em></div><div class="b2-metrics"><div><span>Bundle cost</span><strong>'+money(c.cost)+'</strong></div><div><span>Selling price</span><strong>'+money(c.sell)+'</strong></div><div><span>Customer saving</span><strong>'+money(c.saving)+'</strong></div><div><span>Gross profit</span><strong>'+money(c.profit)+'</strong></div><div><span>Gross margin</span><strong>'+c.margin.toFixed(1)+'%</strong></div><div><span>Total weight</span><strong>'+c.weight.toFixed(2)+' kg</strong></div><div><span>Components</span><strong>'+c.count+'</strong></div><div><span>Suppliers</span><strong>'+c.suppliers.length+'</strong></div></div><div class="b2-limit"><span>Lowest stock component</span><strong>'+(c.limiter?esc(c.limiter.name):'Not calculated')+'</strong></div><div class="b2-warnings"><h4>Smart warnings</h4>'+warningHtml+'</div></aside>'}
function view(p){var c=calc(p),st=status(c),componentRows=rows(p).map(directRow).join('');return '<div class="b2" data-b2-builder="'+esc(p.id)+'"><header class="b2-header"><div><span class="b2-eyebrow">POOL SHED · BUNDLE PRODUCT</span><h2>Bundle Builder</h2><p>Link live catalogue SKUs without creating duplicate stock records. Components remain independently stocked, purchased and picked.</p></div><div class="b2-header-actions"><span class="b2-status '+st.key+'"><i></i>'+st.label+'</span><button type="button" data-b2-duplicate>Duplicate bundle</button></div></header><div class="b2-layout"><main><section class="b2-card"><div class="b2-section-head"><div><h3>Bundle configuration</h3><p>Pricing and customer-document behaviour.</p></div></div><div class="b2-form-grid"><label>Pricing method<select data-b2-field="bundlePriceMode"><option value="fixed" '+((p.bundlePriceMode||'fixed')==='fixed'?'selected':'')+'>Fixed selling price</option><option value="sum" '+(p.bundlePriceMode==='sum'?'selected':'')+'>Sum of components</option><option value="sum-discount" '+(p.bundlePriceMode==='sum-discount'?'selected':'')+'>Components minus discount</option></select></label><label>Fixed selling price<input type="number" min="0" step="0.01" data-b2-field="bundleManualRrp" value="'+Number(p.bundleManualRrp||p.rrp||0).toFixed(2)+'"></label><label>Discount %<input type="number" min="0" max="100" step="0.1" data-b2-field="bundleDiscountPercent" value="'+Number(p.bundleDiscountPercent||0)+'"></label><label>Target margin %<input type="number" min="0" max="100" step="1" data-b2-field="bundleTargetMargin" value="'+Number(p.bundleTargetMargin||25)+'"></label><label>Quotation display<select data-b2-field="bundleQuoteDisplay"><option '+((p.bundleQuoteDisplay||'Bundle Name Only')==='Bundle Name Only'?'selected':'')+'>Bundle Name Only</option><option '+(p.bundleQuoteDisplay==='Bundle with Included Products'?'selected':'')+'>Bundle with Included Products</option><option '+(p.bundleQuoteDisplay==='Show Full Component Breakdown'?'selected':'')+'>Show Full Component Breakdown</option></select></label><label>Invoice display<select data-b2-field="bundleInvoiceDisplay"><option '+((p.bundleInvoiceDisplay||'Show Bundle Only')==='Show Bundle Only'?'selected':'')+'>Show Bundle Only</option><option '+(p.bundleInvoiceDisplay==='Show Bundle Contents'?'selected':'')+'>Show Bundle Contents</option></select></label><label>Packaging weight (kg)<input type="number" min="0" step="0.01" data-b2-field="bundlePackagingWeight" value="'+Number(p.bundlePackagingWeight||0)+'"></label><label>Status<select data-b2-field="bundleEnabled"><option value="Yes" '+((p.bundleEnabled||'Yes')==='Yes'?'selected':'')+'>Active</option><option value="No" '+(p.bundleEnabled==='No'?'selected':'')+'>Draft</option></select></label></div></section><section class="b2-card"><div class="b2-section-head"><div><h3>Linked catalogue products</h3><p>Search existing products, variants or bundles by product name, SKU or barcode.</p></div><span>'+rows(p).length+' linked</span></div><div class="b2-search"><input type="search" data-b2-search placeholder="Search the live product catalogue"><div data-b2-results class="b2-results"></div></div><div class="b2-list">'+(componentRows||'<div class="b2-empty"><strong>No components linked yet</strong><p>Search above and add the first existing catalogue SKU.</p></div>')+'</div><button type="button" class="b2-add" data-b2-focus>+ Add another product</button></section><section class="b2-card"><div class="b2-section-head"><div><h3>Stock simulation</h3><p>Check whether a larger customer order can be fulfilled before adding it to a Sales Order.</p></div><label class="b2-sim">Bundle quantity<input type="number" min="1" value="1" data-b2-sim></label></div><div data-b2-sim-results>'+simulation(c,1)+'</div></section></main>'+dashboard(p,c)+'</div><footer class="b2-save"><div><strong data-b2-save-state>Bundle is up to date</strong><span>Changes update the virtual bundle only. Component product records and stock remain unchanged.</span></div><button type="button" class="secondary" data-b2-discard>Discard</button><button type="button" data-b2-save>Save bundle</button></footer></div>'}
function simulation(c,n){return '<div class="b2-sim-grid">'+c.lines.map(function(r){var s=rawStock(r.product),need=r.qty*n,av=Number(s.available||0),short=Math.max(0,need-av);return '<div><span>'+esc(r.product.name)+' · '+esc(r.product.sku||'')+'</span><strong class="'+(short?'red':'green')+'">'+need+' required · '+av+' available'+(short?' · Need '+short:' · Ready')+'</strong></div>'}).join('')+'</div>'}
var oldTab=window.productProfileTabContent;if(typeof oldTab==='function')window.productProfileTabContent=function(p,s){if(window.productTab==='bundle')return view(p);return oldTab(p,s)};
function current(el){var root=el.closest('[data-b2-builder]');return root&&byId(root.dataset.b2Builder)}
function mark(root){var state=root.querySelector('[data-b2-save-state]');if(state)state.textContent='Unsaved changes';root.classList.add('dirty')}
function save(p){p.productType='Bundle Product';p.bundleEnabled=p.bundleEnabled||'Yes';p.stockTracked=false;var c=calc(p);p.bundleComponentCost=c.cost;p.bundleComponentRrp=c.componentRrp;p.rrp=c.sell;p.bundleComponents=rows(p).map(function(r){var x=byId(r.productId);return (x?x.sku:r.productId)+' | '+r.qty}).join('\n');p.updatedAt=new Date().toISOString();if(typeof window.saveAppData==='function')saveAppData();if(typeof window.toast==='function')toast('Bundle saved. Existing catalogue SKUs remain linked and stock-controlled.');if(typeof window.render==='function')render()}
document.addEventListener('input',function(e){var search=e.target.closest('[data-b2-search]');if(search){var p=current(search),box=search.parentNode.querySelector('[data-b2-results]'),q=search.value.trim().toLowerCase();if(!q){box.innerHTML='';return}var existing=new Set(rows(p).map(function(r){return String(r.productId)}));var matches=all().filter(function(x){if(!x||x.id===p.id||existing.has(String(x.id))||x.hiddenFromCatalogue||x.deleted)return false;var h=[x.name,x.sku,x.barcode,x.supplierSku,x.brand,x.category].join(' ').toLowerCase();return q.split(/\s+/).every(function(t){return h.indexOf(t)>=0})}).slice(0,10);box.innerHTML=matches.map(function(x){var s=isBundle(x)?calc(x):rawStock(x);return '<button type="button" data-b2-add="'+esc(x.id)+'">'+img(x)+'<span><strong>'+esc(x.name)+'</strong><em>'+esc(x.sku||'No SKU')+' · '+(isBundle(x)?'Nested bundle':Number(s.available||0)+' available')+'</em></span><b>'+money(isBundle(x)?calc(x).sell:x.rrp||0)+'</b><i>+</i></button>'}).join('')||'<div class="b2-no-result">No matching live catalogue product.</div>';return}var sim=e.target.closest('[data-b2-sim]');if(sim){var p2=current(sim),out=sim.closest('.b2-card').querySelector('[data-b2-sim-results]');out.innerHTML=simulation(calc(p2),Math.max(1,Number(sim.value||1)));return}var qty=e.target.closest('[data-b2-qty]');if(qty){var p3=current(qty),r=rows(p3).find(function(x){return String(x.productId)===qty.dataset.b2Qty});if(r)r.qty=Math.max(1,Math.floor(Number(qty.value||1)));mark(qty.closest('.b2'));return}var field=e.target.closest('[data-b2-field]');if(field){var p4=current(field),val=field.type==='number'?Number(field.value||0):field.value;p4[field.dataset.b2Field]=val;mark(field.closest('.b2'))}},true);
document.addEventListener('click',function(e){var add=e.target.closest('[data-b2-add]');if(add){var p=current(add);try{flatten(byId(add.dataset.b2Add),1,[p.id],[])}catch(err){toast(err.message);return}p.bundleItems=rows(p).concat({productId:add.dataset.b2Add,qty:1,displayOrder:rows(p).length});save(p);return}var remove=e.target.closest('[data-b2-remove]');if(remove){var p2=current(remove);p2.bundleItems=rows(p2).filter(function(r){return String(r.productId)!==remove.dataset.b2Remove});save(p2);return}var open=e.target.closest('[data-b2-open]');if(open&&typeof window.openProductProfile==='function'){openProductProfile(open.dataset.b2Open);return}var focus=e.target.closest('[data-b2-focus]');if(focus){var input=focus.closest('.b2-card').querySelector('[data-b2-search]');input.focus();input.scrollIntoView({behavior:'smooth',block:'center'});return}var sv=e.target.closest('[data-b2-save]');if(sv){save(current(sv));return}var discard=e.target.closest('[data-b2-discard]');if(discard){if(typeof window.render==='function')render();return}var dup=e.target.closest('[data-b2-duplicate]');if(dup){var p3=current(dup),copy=JSON.parse(JSON.stringify(p3));copy.id='P-'+Date.now();copy.sku=(p3.sku||'BUNDLE')+'-COPY';copy.name=(p3.name||'Bundle')+' Copy';copy.status='Draft';copy.bundleEnabled='No';data.products.push(copy);saveAppData();toast('Bundle duplicated as '+copy.sku+'.');if(typeof window.openProductProfile==='function')openProductProfile(copy.id);else render();return}},true);
function patchProductTypes(){document.querySelectorAll('select[name="productType"],select[data-product-field$="|productType"]').forEach(function(sel){['Standard Product','Bundle Product','Variable Product','Service','Digital Product'].forEach(function(v){if(!Array.from(sel.options).some(function(o){return o.value===v||o.text===v})){var o=document.createElement('option');o.value=v;o.textContent=v;sel.appendChild(o)}})})}
new MutationObserver(patchProductTypes).observe(document.documentElement,{childList:true,subtree:true});patchProductTypes();
window.PoolShedBundleSystem={isBundle:isBundle,calculate:calc,flatten:flatten,mergedComponents:mergedComponents,release:'1'};
})();
